 execFileSync('\''tar'\'',['\''--exclude=.agents/pm'\'','\''-xf'\'',archive,'\''-C'\'',tmp]);
 symlinkSync(path.join(root,'\''node_modules'\''),path.join(tmp,'\''node_modules'\''),'\''junction'\'');
 const file=path.join(tmp,"src/sdk/query/history.ts"),text=readFileSync(file,'\''utf8'\''),needle="const newestFirst = limit === undefined && (compact || options.provenance === true);";if(text.split(needle).length!==2)throw new Error('\''Unsafe mutant target changed'\'');writeFileSync(file,text.replace(needle,"const newestFirst = false;"));
 const report=path.join(tmp,'\''negative.json'\'');
