 const data=JSON.parse(readFileSync(report,'\''utf8'\'')),failures=data.testResults.flatMap(s=>s.assertionResults).filter(t=>t.status==='\''failed'\'');
 const proven=result.status===1 && data.numFailedTests===1 && data.testResults.every(s=>s.message==='\'''\'') && failures.length===1 && failures[0].title==="keeps the newest of 251 native entries and resumes every older entry exactly once" && failures[0].failureMessages.some(m=>m.includes('\''AssertionError'\'')&&m.includes("to be 251"));
 console.log(JSON.stringify({candidate:'\''aff043f08ea0bd4a14b30af6f420d0f7f01c910f'\'',unsafe_condition:"intentional newestFirst=false mutant",file:"src/sdk/query/history.ts",test:"keeps the newest of 251 native entries and resumes every older entry exactly once",negative_control_proven:proven}));
 if(!proven)console.error(JSON.stringify({status:result.status,suites:data.testResults.map(s=>({message:s.message})),failures}));
 process.exitCode=proven?1:3;
} catch(error){console.error(error);process.exitCode=3;} finally{rmSync(tmp,{recursive:true,force:true});}'
